require 'thread'
require 'securerandom'
require 'json'
require 'bcrypt'

class PaymentProcessor
  SHUTDOWN_GRACE_PERIOD = 30

  def initialize
    @mutex = Mutex.new
    @transactions = {}
    @shutting_down = false
    @pending_count = 0
    @shutdown_cv = ConditionVariable.new
    setup_signal_handlers
  end

  def setup_signal_handlers
    Signal.trap('TERM') { initiate_shutdown }
    Signal.trap('INT') { initiate_shutdown }
  end

  def initiate_shutdown
    @shutting_down = true
    Thread.new { graceful_shutdown }
  end

  def graceful_shutdown
    deadline = Time.now + SHUTDOWN_GRACE_PERIOD
    @mutex.synchronize do
      while @pending_count > 0 && Time.now < deadline
        @shutdown_cv.wait(@mutex, 1)
      end
    end
    finalize_pending_transactions
    exit(0)
  end

  def finalize_pending_transactions
    @mutex.synchronize do
      @transactions.each do |id, txn|
        if txn[:state] == :authorized
          txn[:state] = :settled
          commit_to_ledger(txn)
        end
      end
    end
  end

  def process_payment(user_id, amount_cents, idempotency_key)
    return { error: 'shutting_down' } if @shutting_down && !has_inflight?(idempotency_key)

    @mutex.synchronize do
      existing = find_by_idempotency_key(idempotency_key)
      return { success: true, transaction_id: existing[:id] } if existing

      txn_id = SecureRandom.uuid
      txn = {
        id: txn_id,
        user_id: user_id,
        amount_cents: amount_cents,
        idempotency_key: idempotency_key,
        state: :pending,
        created_at: Time.now,
        attempts: 0
      }
      @transactions[txn_id] = txn
      @pending_count += 1
    end

    result = execute_payment_flow(idempotency_key)
    result
  end

  def execute_payment_flow(idempotency_key)
    txn = nil
    @mutex.synchronize do
      txn = find_by_idempotency_key(idempotency_key)
    end
    return { error: 'not_found' } unless txn

    authorize_result = call_payment_gateway(txn)

    @mutex.synchronize do
      txn = @transactions[txn[:id]]
      if authorize_result[:success]
        txn[:state] = :authorized
        txn[:gateway_ref] = authorize_result[:reference]
      else
        txn[:state] = :failed
        @pending_count -= 1
        @shutdown_cv.signal
        return { error: 'authorization_failed' }
      end
    end

    capture_result = capture_payment(txn)

    @mutex.synchronize do
      if capture_result[:success]
        txn[:state] = :captured
        txn[:captured_amount] = capture_result[:amount]
        @pending_count -= 1
        @shutdown_cv.signal
        { success: true, transaction_id: txn[:id], amount: txn[:captured_amount] }
      else
        txn[:state] = :capture_failed
        schedule_retry(txn)
        { error: 'capture_pending', transaction_id: txn[:id] }
      end
    end
  end

  def apply_discount(txn_id, discount_cents)
    @mutex.synchronize do
      txn = @transactions[txn_id]
      return { error: 'not_found' } unless txn
      return { error: 'invalid_state' } unless [:pending, :authorized].include?(txn[:state])

      new_amount = txn[:amount_cents] - discount_cents
      txn[:amount_cents] = new_amount
      { success: true, new_amount: new_amount }
    end
  end

  def refund_payment(txn_id, refund_amount_cents)
    @mutex.synchronize do
      txn = @transactions[txn_id]
      return { error: 'not_found' } unless txn
      return { error: 'invalid_state' } unless txn[:state] == :captured
      return { error: 'excessive_refund' } if refund_amount_cents > txn[:captured_amount]

      txn[:refunded_amount] = (txn[:refunded_amount] || 0) + refund_amount_cents
      txn[:state] = :refunded if txn[:refunded_amount] >= txn[:captured_amount]
      process_refund_gateway(txn, refund_amount_cents)
    end
  end

  private

  def has_inflight?(idempotency_key)
    @mutex.synchronize do
      @transactions.values.any? { |t| t[:idempotency_key] == idempotency_key && t[:state] != :failed }
    end
  end

  def find_by_idempotency_key(key)
    @transactions.values.find { |t| t[:idempotency_key] == key }
  end

  def call_payment_gateway(txn)
    sleep(0.1) # simulate network
    { success: true, reference: "GW-#{SecureRandom.hex(8)}" }
  end

  def capture_payment(txn)
    sleep(0.05) # simulate network
    { success: true, amount: txn[:amount_cents] }
  end

  def commit_to_ledger(txn)
    # Writes to persistent ledger - in shutdown path this settles authorized txns
    # The amount committed is txn[:amount_cents] at time of settlement
  end

  def schedule_retry(txn)
    txn[:attempts] += 1
  end

  def process_refund_gateway(txn, amount)
    { success: true, refunded: amount }
  end
end
